(()=>{
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(name,cls='')=>`<svg class="icon ${cls}" aria-hidden="true" focusable="false"><use href="/assets/icons.svg#${name}"></use></svg>`;
const course=()=>window.BoraCourses[0];
const lessonPhoto=l=>window.BoraLessonPhotos?.[l.id]||{src:'/assets/rio-panorama.webp',place:'Бразилия'};
function lessonFigure(l){const p=lessonPhoto(l);return `<figure class="lesson-landscape"><img src="${p.src}" alt="${esc(p.place)}" width="960" height="480"><figcaption><strong>${esc(p.place)}</strong><span>Твоя следующая остановка</span></figcaption>${p.url?`<details class="photo-credit"><summary>Об этой фотографии</summary><p><a href="${esc(p.url)}" target="_blank" rel="noopener noreferrer">${esc(p.author)} · ${esc(p.source)}</a> · <a href="${esc(p.licenseUrl)}" target="_blank" rel="noopener noreferrer">${esc(p.license)}</a>. Кадрирование и сжатие для сайта.</p></details>`:''}</figure>`}
let disposeCarousel=()=>{};
function stop(){disposeCarousel();disposeCarousel=()=>{}}
function carousel(){const track=document.querySelector('#lesson-carousel-track');if(!track)return;const prev=document.querySelector('#carousel-prev'),next=document.querySelector('#carousel-next'),label=document.querySelector('#carousel-position');const update=()=>{const max=Math.max(0,track.scrollWidth-track.clientWidth);prev.disabled=track.scrollLeft<=2;next.disabled=track.scrollLeft>=max-2;const children=track.children,bounds=track.getBoundingClientRect(),visible=Array.from(children).map((node,index)=>{const r=node.getBoundingClientRect();return r.right>bounds.left+8&&r.left<bounds.right-8?index+1:0}).filter(Boolean);const text=`Уроки ${visible[0]||1}–${visible.at(-1)||children.length} из ${children.length}`;if(label.textContent!==text)label.textContent=text};const move=direction=>track.scrollBy({left:direction*track.clientWidth,behavior:window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});prev.onclick=()=>move(-1);next.onclick=()=>move(1);track.onscroll=update;track.onkeydown=e=>{if(e.target!==track)return;if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();if(e.key==='Home'||e.key==='End')track.scrollTo({left:e.key==='Home'?0:track.scrollWidth,behavior:'instant'});else move(e.key==='ArrowRight'?1:-1)}};window.addEventListener?.('resize',update);disposeCarousel=()=>{window.removeEventListener?.('resize',update);track.onscroll=null;track.onkeydown=null};update()}

const norm=s=>String(s??'').normalize('NFD').replace(/\p{M}/gu,'').toLocaleLowerCase('ru-RU').trim();
const images=['rio-palms','brazil-colors','rio-coast','rio-panorama','rio-coast'];
function stats(u){const c=course(),done=c.lessons.filter(l=>u.courseProgress?.['pt/'+l.id]?.done).length;return {done,total:c.lessons.length,percent:Math.round(done/c.lessons.length*100),due:window.BoraStudy?.due(u)||[],next:window.BoraStudy?.next(u)||c.lessons[0]}}
function home(u){const s=stats(u),signed=window.BoraAccount?.signedIn===true;if(!signed)return `<section class="brazil-hero welcome-public"><img class="brazil-hero-image" src="/assets/rio-panorama.webp" alt="Побережье Рио-де-Жанейро" width="966" height="544"><div class="brazil-hero-shade"></div><div class="brazil-hero-copy"><span class="glass-label">Бразильский португальский</span><h1>Начни говорить.<br>С самых первых слов.</h1><p>Объяснения на русском, аудио и упражнения.<br>Учись по шагам, без спешки.</p><a class="btn yellow" href="#account/register">Я здесь впервые — создать аккаунт</a><p class="welcome-signin">Уже есть аккаунт? <a href="#account/login">Войти</a></p></div></section><section class="welcome-steps" aria-label="Как начать"><div><b>1</b><h2>Создай аккаунт</h2><p>Понадобятся почта и пароль.</p></div><div><b>2</b><h2>Начни с первых слов</h2><p>Или выбери проверку, если уже немного знаешь язык.</p></div><div><b>3</b><h2>Продолжай в своём темпе</h2><p>Занятие сохраняется на том шаге, где остановился.</p></div></section>`;const hasStart=!!u.diagnosis||!!u.currentLesson||Object.keys(u.courseProgress||{}).length>0,g=u.courseProgress?.['pt/'+s.next.id]?.guided,allDone=s.done===s.total&&!(g&&g.index<18)&&u.learningPath?.lesson!==s.next.id;return `<div class="welcome-line"><div><span class="overline">ТВОЁ ОБУЧЕНИЕ</span><h1>${esc(u.name||'Привет')}${u.name?', продолжим?':'! Начнём?'}</h1><p>Здесь — твой следующий шаг. Полный список тем находится во вкладке «Все занятия».</p></div></div>${hasStart?`<section class="panel continue-learning"><span class="overline">${allDone?'ОСНОВНОЙ КУРС ПРОЙДЕН':'СЛЕДУЮЩЕЕ ЗАНЯТИЕ'}</span><h2>${allDone?'Время повторить и закрепить':esc(s.next.title)}</h2><p>${allDone?'Выбери тему для повторения или учебный пробник.':g&&g.index<18?'Продолжим с того места, где ты остановился: шаг '+(g.index+1)+' из 19.':esc(s.next.scene)}</p><a class="btn yellow" href="#${allDone?'courses/pt':'courses/pt/'+s.next.id}">${allDone?'Выбрать занятие для повторения':'Продолжить занятие →'}</a><div class="mini-progress"><div><span>Завершено</span><strong>${s.done} / ${s.total} уроков</strong></div><progress value="${s.done}" max="${s.total}" aria-label="Завершено занятий"></progress></div></section>`:`<section class="panel"><h2>С чего начнём?</h2><div class="start-options"><div><h3>Я начинаю с нуля</h3><p>Откроем приветствия и первые фразы. Никаких знаний заранее не нужно.</p><button class="btn yellow" data-start-basics>Начать первый урок →</button></div><div><h3>Я уже немного знаю</h3><p>Короткая проверка поможет выбрать подходящее начало. Это необязательно.</p><a class="btn alt" href="#diagnosis">Проверить знания →</a></div></div></section>`}${s.due.length?`<section class="review-strip"><div><h2>Можно повторить</h2><p>${esc(s.due[0].l.title)}</p></div><a class="btn alt" href="#review/pt/${s.due[0].l.id}">Повторить тему</a></section>`:''}<details class="learning-options"><summary>Хочу изменить начало обучения</summary><p><button class="btn alt" data-start-basics>Начать с самых первых фраз</button></p><p><a href="#diagnosis">Пройти начальную проверку знаний</a></p><p>Уже выполненные занятия сохранятся.</p></details>`}

function filterLessons(lessons,records,{q='',module='all',status='all'}={}){const term=norm(q);return lessons.filter(l=>{const r=records?.['pt/'+l.id],state=r?.done?'done':r?.stage||r?.guided?.index>0?'started':'new';return (module==='all'||l.module===module)&&(status==='all'||state===status)&&(!term||norm([l.title,l.topic,l.scene,l.idea,...(l.examples||[]).flat()].join(' ')).includes(term))})}
function catalog(u,c=course()){const s=stats(u),params=new URLSearchParams(location.hash.split('?')[1]||''),mi=params.get('module')||'all',q=(params.get('q')||'').slice(0,100),status=['all','new','started','done'].includes(params.get('status'))?params.get('status'):'all';return `<div class="page-heading"><span class="overline">ПРОГРАММА ОБУЧЕНИЯ</span><h1>Все занятия</h1><p>30 тем по порядку — от приветствий до бытового общения. Выбирай любую тему или продолжай со вкладки «Учиться».</p></div><section class="lesson-browser" aria-label="Поиск и выбор урока"><div class="section-head"><h2>Выбери занятие</h2><span id="lesson-count" class="small" role="status" aria-live="polite">${c.lessons.length} уроков</span></div><div class="lesson-filters"><label class="search-field">${icon('search')}<input id="lesson-search" type="search" maxlength="100" value="${esc(q)}" placeholder="Найти тему: кафе, прошлое, знакомство…" aria-label="Поиск по урокам"></label><label class="status-filter">${icon('sliders-horizontal')}<select id="lesson-status" aria-label="Состояние уроков">${[['all','Все уроки'],['new','Новые'],['started','Начатые'],['done','Пройденные']].map(([v,label])=>`<option value="${v}" ${v===status?'selected':''}>${label}</option>`).join('')}</select></label></div><div class="module-filters" role="group" aria-label="Модуль курса"><button type="button" data-module="all" aria-pressed="${mi==='all'}">Весь маршрут</button>${c.modules.map((m,i)=>`<button type="button" data-module="${i}" aria-pressed="${mi===String(i)}"><span>${String(i+1).padStart(2,'0')}</span> ${esc(m.title)}</button>`).join('')}</div><div class="lesson-card-grid">${c.lessons.map((l,i)=>{const r=u.courseProgress?.['pt/'+l.id],done=r?.done,started=(r?.stage||r?.guided?.index>0)&&!done;return `<article class="lesson-card ${done?'is-complete':''}" data-lesson-id="${l.id}"><a href="#unit/${l.id}"><div class="lesson-card-photo"><img src="${lessonPhoto(l).src}" alt="${esc(lessonPhoto(l).place)}" width="480" height="260" loading="lazy"><span>${esc(lessonPhoto(l).place)}</span></div><div class="lesson-card-top"><span class="lesson-index">${done?icon('check'):String(i+1).padStart(2,'0')}</span><span class="lesson-state">${done?'Пройдено':started?'Продолжаем':'20–35 минут'}</span>${icon('arrow-up-right')}</div><span class="lesson-module">${esc(l.module)}</span><h3>${esc(l.title)}</h3><p>${esc(l.scene)}</p><span class="lesson-topic">${icon('book-open')} ${esc(l.topic)}</span></a></article>`}).join('')}</div><div id="lesson-empty" class="empty-search" hidden>${icon('search')}<h3>Такой темы пока не нашли</h3><p>Попробуй другое слово или сбрось фильтры.</p><button class="btn alt" id="reset-filters">Показать весь маршрут</button></div></section><div class="quiet-note">${icon('circle-help')} Курс — основа для общения. Подготовка к Celpe-Bras дополнительно требует аудирования, развёрнутого письма и устной практики.</div>`}
let focus=false;
function focusButton(){return `<button class="btn alt focus-button" id="study-focus" aria-pressed="${focus}">${icon(focus?'minimize-2':'maximize-2')} ${focus?'Обычный вид':'Без отвлечений'}</button>`}
function steps(stage){return `<div class="lesson-stepper" aria-label="Этапы урока">${['Разобраться','Выбрать','Проверить','Написать','Поговорить'].map((text,i)=>`<span class="${i===stage?'current':i<stage?'passed':''}" ${i===stage?'aria-current="step"':''}><b>${i<stage?'✓':i+1}</b><span>${text}</span></span>`).join('')}</div>`}
function applyFocus(){document.body?.classList.toggle('study-focus',focus);const button=document.querySelector('#study-focus');if(button){button.setAttribute('aria-pressed',String(focus));button.innerHTML=icon(focus?'minimize-2':'maximize-2')+(focus?' Обычный вид':' Без отвлечений')}}
function refresh(route){if(!document.body)return;const skip=document.querySelector('.skip-link');if(skip)skip.onclick=e=>{e.preventDefault();document.querySelector('#app')?.focus()};const isLesson=route==='courses'&&location.hash.split('?')[0].split('/').length>=3;document.body.dataset.route=route;document.body.dataset.lesson=String(isLesson);if(!isLesson)focus=false;applyFocus();document.querySelectorAll('[data-nav]').forEach(a=>{const key=a.dataset.nav,current=key===(['review','courses','test','unit'].includes(route)?'courses':['practice','live'].includes(route)?'assistant':route);if(current)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});const caption=document.querySelector('#page-caption');if(caption)caption.textContent=({exam:'Пробный экзамен',test:'Проверим знания',home:'Учиться',courses:'Все занятия',unit:'О занятии',dictionary:'Словарь и правила',progress:'Каждый шаг считается',assistant:'Разберёмся вместе',practice:'Время поговорить',account:'Твой аккаунт',start:'Давай познакомимся',review:'Вспомним вместе',diagnosis:'Твоя точка старта',result:'Твой маршрут',live:'Живой разговор'}[route]||'Português do Brasil')}
function bind(u){carousel();const search=document.querySelector('#lesson-search');if(search){const c=course(),params=new URLSearchParams(location.hash.split('?')[1]||'');let module=params.get('module')||'all';const status=document.querySelector('#lesson-status');const apply=()=>{const mod=module==='all'?'all':c.modules[Number(module)]?.title||'all';const ids=new Set(filterLessons(c.lessons,u.courseProgress,{q:search.value,module:mod,status:status.value}).map(l=>l.id));document.querySelectorAll('[data-lesson-id]').forEach(card=>card.hidden=!ids.has(card.dataset.lessonId));document.querySelector('#lesson-count').textContent=`Найдено: ${ids.size} из ${c.lessons.length}`;document.querySelector('#lesson-empty').hidden=!!ids.size;document.querySelectorAll('[data-module]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.module===module)));const p=new URLSearchParams();if(search.value)p.set('q',search.value);if(module!=='all')p.set('module',module);if(status.value!=='all')p.set('status',status.value);history.replaceState(null,'','#courses/pt'+(p.size?'?'+p.toString():''))};search.oninput=apply;status.onchange=apply;document.querySelectorAll('[data-module]').forEach(b=>b.onclick=()=>{module=b.dataset.module;apply()});document.querySelector('#reset-filters').onclick=()=>{module='all';search.value='';status.value='all';apply();search.focus()};apply()}const button=document.querySelector('#study-focus');if(button)button.onclick=()=>{focus=!focus;applyFocus()}}
window.BoraUI={home,catalog,lessonPhoto,lessonFigure,stop,filterLessons,icon,focusButton,steps,refresh,bind,esc};
})();
